/* From Uiverse.io by SouravBandyopadhyay - Tags: input, light, transition */
.__UIV_SCOPE__ .inp-border {
  padding: 5px;
  margin: 2em 1em;
  border-radius: 50px;
  max-width: 300px;
}

.__UIV_SCOPE__ .input {
  text-align: center;
  padding: 15px;
  outline: none;
  border: double 0;
  background: #252525;
  border-radius: 50px;
  position: relative;
  box-sizing: border-box;
  display: block;
  width: 100%;
  font-size: 1.5rem;
}

.__UIV_SCOPE__ .a1 {
  background: linear-gradient(
    330.28deg,
    #ff6e1d 100%,
    #ff6e1d 100%,
    #ff6e1d 100%
  );
}

.__UIV_SCOPE__ .a1 > input {
  color: #caab98;
}

.__UIV_SCOPE__ .a1 > input::placeholder {
  color: #ff6e1d;
  opacity: 0.6;
}

.__UIV_SCOPE__ .inp-border:focus-within {
  background: linear-gradient(
    330.28deg,
    #2cfff2 0%,
    #1e78ff 30.73%,
    #ff54a6 55.73%,
    #ff6e1d 79.17%,
    #ff3e3e 100%
  );
}

.__UIV_SCOPE__ .inp-border:hover {
  background: linear-gradient(
    330.28deg,
    #2cfff2 0%,
    #1e78ff 30.73%,
    #ff54a6 55.73%,
    #ff6e1d 79.17%,
    #ff3e3e 100%
  );
}
